+  @ParameterizedTest
+  @MethodSource("commandEncodingReentrancyCases")
+  void sameClientReentrantQueryDuringCommandEncodingDoesNotEndOuterQuery(
+      boolean chunkedOuterQuery, boolean sameQuery) throws Exception {
+    CountDownLatch nestedWorkerCompleted = new CountDownLatch(1);
+    CountDownLatch outerWorkerCompleted = new CountDownLatch(1);
+    CountDownLatch outerBlocked = new CountDownLatch(1);
+    CountDownLatch releaseOuter = new CountDownLatch(1);
+    AtomicReference<InfluxDB> clientReference = new AtomicReference<>();
+    AtomicReference<Thread> nestedWorker = new AtomicReference<>();
+    AtomicReference<Thread> outerWorker = new AtomicReference<>();
+    AtomicBoolean reenter = new AtomicBoolean(true);
+    AtomicBoolean nestedSucceeded = new AtomicBoolean();
+    AtomicInteger queryRequests = new AtomicInteger();
+    ThreadPoolExecutor executor =
+        new ThreadPoolExecutor(0, Integer.MAX_VALUE, 60, SECONDS, new SynchronousQueue<>()) {
+          @Override
+          protected void afterExecute(Runnable runnable, Throwable error) {
+            if (Thread.currentThread() == nestedWorker.get()) {
+              nestedWorkerCompleted.countDown();
+            }
+            if (Thread.currentThread() == outerWorker.get()) {
+              outerWorkerCompleted.countDown();
+            }
+          }
+        };
+    Query query =
+        new Query("SELECT * FROM cpu", "mydb") {
+          @Override
+          public String getCommandWithUrlEncoded() {
+            if (reenter.compareAndSet(true, false)) {
+              Query nestedQuery = sameQuery ? this : new Query("SELECT * FROM nested", "mydb");
+              clientReference
+                  .get()
+                  .query(nestedQuery, result -> nestedSucceeded.set(true), error -> {});
+              await(nestedWorkerCompleted);
+              outerBlocked.countDown();
+              await(releaseOuter);
+            }
+            return super.getCommandWithUrlEncoded();
+          }
+        };
+    try (InfluxDB client =
+        InfluxDBFactory.connect(
+            "http://localhost:8086",
+            new OkHttpClient.Builder()
+                .dispatcher(new Dispatcher(executor))
+                .addInterceptor(
+                    chain -> {
+                      if (!chain.request().url().encodedPath().endsWith("/query")) {
+                        return response(chain, SUCCESS);
+                      }
+                      if (queryRequests.getAndIncrement() == 0) {
+                        nestedWorker.set(Thread.currentThread());
+                        return response(chain, SUCCESS);
+                      }
+                      outerWorker.set(Thread.currentThread());
+                      throw new IOException("outer transport failure");
+                    }))) {
+      clientReference.set(client);
+      FutureTask<Void> outerQueryTask =
+          new FutureTask<>(
+              () -> {
+                if (chunkedOuterQuery) {
